import { GENERATORS } from './placeholder/registry';

/**
 * Asset manifest (AGENT.md §6, §10): records the source and license of every
 * asset so licensing stays clear as art is swapped in.
 *
 * All current entries are procedural placeholders generated by code in this
 * repo (original work, no third-party material). Photoreal assets replacing
 * them must be registered here with their real source and license, and AI
 * generated or photographed assets require their generation/model-release
 * records kept alongside.
 */
export interface AssetManifestEntry {
  id: string;
  source: 'procedural-placeholder';
  license: string;
  notes?: string;
}

export const PLACEHOLDER_LICENSE =
  'Original procedural artwork generated in-repo. Placeholder pending licensed photoreal assets.';

export const ASSET_MANIFEST: Record<string, AssetManifestEntry> = Object.fromEntries(
  Object.keys(GENERATORS).map((id) => [
    id,
    {
      id,
      source: 'procedural-placeholder' as const,
      license: PLACEHOLDER_LICENSE,
      notes: 'Generated by src/assets/placeholder generators; same layer/anchor system as final art.',
    },
  ]),
);

export function manifestEntry(id: string): AssetManifestEntry | undefined {
  return ASSET_MANIFEST[id];
}
